package pe.edu.grupo4.carga.service;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.mockito.junit.jupiter.MockitoSettings; import org.mockito.quality.Strictness; import pe.edu.grupo4.base.entity.*; import pe.edu.grupo4.base.repository.*; import pe.edu.grupo4.carga.dto.*; import pe.edu.grupo4.carga.entity.CargaAcademica; import pe.edu.grupo4.carga.repository.CargaAcademicaRepository; import pe.edu.grupo4.shared.exception.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) @MockitoSettings(strictness=Strictness.LENIENT) class CargaAcademicaServiceTest {
 @Mock CargaAcademicaRepository cargas; @Mock DocenteRepository docentes; @Mock CursoRepository cursos; @Mock SedeRepository sedes; @Mock DisponibilidadDocenteRepository disponibilidades; @InjectMocks CargaAcademicaServiceImpl service;
 Docente docente; Curso curso; Sede sede; Sede sede2; CargaAcademicaRequest req;
 @BeforeEach void setup(){docente=new Docente(1L,"Ana","Torres","Programación",true,20);curso=new Curso(1L,"INF201","POO","Programación",4);sede=new Sede(1L,"Miraflores","Miraflores");sede2=new Sede(2L,"San Isidro","San Isidro");req=new CargaAcademicaRequest("2026-2",1L,1L," A ",1L,DayOfWeek.MONDAY,LocalTime.of(18,0),LocalTime.of(20,0));when(docentes.findById(1L)).thenReturn(Optional.of(docente));when(cursos.findById(1L)).thenReturn(Optional.of(curso));when(sedes.findById(1L)).thenReturn(Optional.of(sede));when(cargas.findByDocenteIdAndEstado(1L,CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(new ArrayList<>());when(disponibilidades.findByDocenteIdAndDiaSemana(1L,DayOfWeek.MONDAY)).thenReturn(List.of(avail(sede)));when(cargas.save(any())).thenAnswer(i->{CargaAcademica c=i.getArgument(0);if(c.getId()==null)c.setId(10L);return c;});}
 @Test void createsLoadAndReportsWeeklyHours(){var response=service.crear(req);assertEquals("A",response.seccion());assertEquals(4,response.horasAcumuladas());assertEquals("2026-2",response.cicloAcademico());}
 @Test void rejectsNonPositiveRange(){var invalid=new CargaAcademicaRequest("2026-2",1L,1L,"A",1L,DayOfWeek.MONDAY,LocalTime.NOON,LocalTime.NOON);assertThrows(IllegalArgumentException.class,()->service.crear(invalid));}
 @Test void rejectsExactOverlap(){when(cargas.findByDocenteIdAndEstado(1L,CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(List.of(existing(sede,LocalTime.of(18,0),LocalTime.of(20,0))));assertTrue(assertThrows(ConflictoNegocioException.class,()->service.crear(req)).getMessage().contains("Cruce horario"));}
 @Test void rejectsPartialOverlap(){when(cargas.findByDocenteIdAndEstado(1L,CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(List.of(existing(sede,LocalTime.of(19,0),LocalTime.of(21,0))));assertThrows(ConflictoNegocioException.class,()->service.crear(req));}
 @Test void rejectsDifferentCampusWithLessThanHour(){when(cargas.findByDocenteIdAndEstado(1L,CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(List.of(existing(sede2,LocalTime.of(17,15),LocalTime.of(18,0))));assertTrue(assertThrows(ConflictoNegocioException.class,()->service.crear(req)).getMessage().contains("Tiempo de traslado"));}
 @Test void permitsExactlySixtyMinutesBetweenCampuses(){when(cargas.findByDocenteIdAndEstado(1L,CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(List.of(existing(sede2,LocalTime.of(16,0),LocalTime.of(17,0))));assertDoesNotThrow(()->service.crear(req));}
 @Test void permitsBackToBackSameCampus(){when(cargas.findByDocenteIdAndEstado(1L,CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(List.of(existing(sede,LocalTime.of(16,0),LocalTime.of(18,0))));assertDoesNotThrow(()->service.crear(req));}
 @Test void rejectsOutsideAvailability(){when(disponibilidades.findByDocenteIdAndDiaSemana(1L,DayOfWeek.MONDAY)).thenReturn(List.of());assertTrue(assertThrows(ConflictoNegocioException.class,()->service.crear(req)).getMessage().contains("disponibilidad"));}
 @Test void rejectsWrongSpecialty(){curso.setEspecialidadRequerida("Biología");assertTrue(assertThrows(ConflictoNegocioException.class,()->service.crear(req)).getMessage().contains("Biología"));}
 @Test void rejectsWeeklyLimit(){docente.setMaxHorasSemanales(1);assertTrue(assertThrows(ConflictoNegocioException.class,()->service.crear(req)).getMessage().contains("máximo"));}
 @Test void editsAndExcludesCurrentAssignmentFromRules(){CargaAcademica old=existing(sede,LocalTime.of(18,0),LocalTime.of(20,0));old.setId(10L);old.setCicloAcademico("2026-2");when(cargas.findById(10L)).thenReturn(Optional.of(old));when(cargas.findByDocenteIdAndEstado(1L,CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(List.of(old));assertEquals(10L,service.actualizar(10L,req).id());}
 @Test void cannotEditCancelledLoad(){CargaAcademica old=existing(sede,LocalTime.of(18,0),LocalTime.of(20,0));old.setId(10L);old.setEstado(CargaAcademica.EstadoCarga.ANULADA);when(cargas.findById(10L)).thenReturn(Optional.of(old));assertThrows(ConflictoNegocioException.class,()->service.actualizar(10L,req));}
 @Test void annulsLoad(){CargaAcademica old=existing(sede,LocalTime.of(18,0),LocalTime.of(20,0));old.setId(10L);when(cargas.findById(10L)).thenReturn(Optional.of(old));service.anular(10L);assertEquals(CargaAcademica.EstadoCarga.ANULADA,old.getEstado());verify(cargas).save(old);}
 @Test void missingLoadReturnsNotFound(){when(cargas.findById(99L)).thenReturn(Optional.empty());assertThrows(RecursoNoEncontradoException.class,()->service.obtener(99L));}
 @Test void loadsExistingAndFilters(){CargaAcademica c=existing(sede,LocalTime.of(18,0),LocalTime.of(20,0));c.setId(10L);when(cargas.findById(10L)).thenReturn(Optional.of(c));when(cargas.findByEstado(CargaAcademica.EstadoCarga.ACTIVA)).thenReturn(List.of(c));assertEquals(10L,service.obtener(10L).id());assertEquals(1,service.listar("2026-2",1L,1L).size());assertTrue(service.listar("other",2L,2L).isEmpty());}
 @Test void rejectsMissingCourse(){when(cursos.findById(1L)).thenReturn(Optional.empty());assertThrows(RecursoNoEncontradoException.class,()->service.crear(req));}
 @Test void rejectsMissingCampus(){when(sedes.findById(1L)).thenReturn(Optional.empty());assertThrows(RecursoNoEncontradoException.class,()->service.crear(req));}
 private DisponibilidadDocente avail(Sede s){return new DisponibilidadDocente(1L,docente,DayOfWeek.MONDAY,LocalTime.of(8,0),LocalTime.of(22,0),s);}
 private CargaAcademica existing(Sede s,LocalTime start,LocalTime end){CargaAcademica c=new CargaAcademica();c.setId(4L);c.setCicloAcademico("2026-2");c.setDocente(docente);c.setCurso(curso);c.setSeccion("X");c.setSede(s);c.setDiaSemana(DayOfWeek.MONDAY);c.setHoraInicio(start);c.setHoraFin(end);c.setEstado(CargaAcademica.EstadoCarga.ACTIVA);return c;}
}
